#!/bin/sh
set -eu

until wp db check --allow-root >/dev/null 2>&1; do sleep 2; done
site_url="${KILN_CLEANUP_SITE_URL:-http://localhost:8080}"
wp core is-installed --allow-root >/dev/null 2>&1 || wp core install --url="$site_url" --title='Kiln Cleanup Smoke' --admin_user=admin --admin_password=not-a-real-secret --admin_email=admin@example.test --skip-email --allow-root
wp option update home "$site_url" --allow-root
wp option update siteurl "$site_url" --allow-root
rm -rf wp-content/plugins/kiln-cleanup
cp -R /workspace/kiln-cleanup wp-content/plugins/kiln-cleanup
mkdir -p wp-content/plugins/kiln-cleanup/vendor
cat > wp-content/plugins/kiln-cleanup/vendor/autoload.php <<'PHP'
<?php
spl_autoload_register(static function (string $class): void {
    if (str_starts_with($class, 'KilnCleanup\\')) {
        require __DIR__ . '/../src/' . str_replace('\\', '/', substr($class, 12)) . '.php';
    }
});
PHP
wp plugin activate kiln-cleanup --allow-root
wp eval 'global $wpdb; foreach (["kiln_cleanup_jobs","kiln_cleanup_candidates","kiln_cleanup_audit_events","kiln_cleanup_quarantines"] as $table) { if ($wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $wpdb->prefix . $table)) !== $wpdb->prefix . $table) { throw new RuntimeException("Missing table: " . $table); }}' --allow-root
wp eval 'global $wpdb; foreach (["band","policy_version"] as $column) { if ($wpdb->get_var("SHOW COLUMNS FROM {$wpdb->prefix}kiln_cleanup_candidates LIKE \"{$column}\"") !== $column) { throw new RuntimeException("Missing candidate column: " . $column); }} $bandColumn = $wpdb->get_row("SHOW COLUMNS FROM {$wpdb->prefix}kiln_cleanup_candidates LIKE \"band\"", ARRAY_A); if (($bandColumn["Type"] ?? "") !== "varchar(32)") { throw new RuntimeException("Candidate band column is too narrow"); } $codec = new \KilnCleanup\Application\ReviewJobSnapshotCodec(); $job = (new \KilnCleanup\Infrastructure\WpdbReviewJobRepository())->create($codec->policySnapshot(new \KilnCleanup\Detection\DetectionPolicy("smoke-v1")), $codec->filterSnapshot(new \KilnCleanup\Domain\InventoryFilter()), 1); if ($job->state->value !== "draft") { throw new RuntimeException("Unexpected new job state"); }' --allow-root
wp eval 'global $wpdb; $login = "quarantine-smoke"; $userId = wp_create_user($login, "not-a-real-secret", "quarantine-smoke@example.test"); if (is_wp_error($userId)) { $existing = get_user_by("login", $login); if (! $existing instanceof WP_User) { throw new RuntimeException("Smoke user could not be created or recovered."); } $userId = $existing->ID; } $userId = (int) $userId; (new WP_User($userId))->set_role("subscriber"); $codec = new \KilnCleanup\Application\ReviewJobSnapshotCodec(); $jobs = new \KilnCleanup\Infrastructure\WpdbReviewJobRepository(); $job = $jobs->create($codec->policySnapshot(new \KilnCleanup\Detection\DetectionPolicy("quarantine-smoke-v1")), $codec->filterSnapshot(new \KilnCleanup\Domain\InventoryFilter()), 1); $wpdb->update($wpdb->prefix . "kiln_cleanup_jobs", ["state" => "completed"], ["id" => $job->id]); (new \KilnCleanup\Infrastructure\WpdbCandidateSnapshotRepository())->insert(new \KilnCleanup\Domain\CandidateSnapshot($job->id, $userId, 75, "eligible_for_quarantine", "quarantine-smoke-v1", ["blocked_email_domain"])); $service = new \KilnCleanup\Application\QuarantineService(new \KilnCleanup\Infrastructure\WpdbQuarantineCandidateRepository(), new \KilnCleanup\Infrastructure\WpdbQuarantineRepository(), new \KilnCleanup\Infrastructure\WordPressUserAccountGateway(), new \KilnCleanup\Infrastructure\QuarantineAuditRecorder()); $service->quarantine($job->id, $userId, new \KilnCleanup\Detection\DetectionPolicy("quarantine-smoke-v1"), 1); if (get_user_meta($userId, "_kiln_cleanup_quarantined", true) !== "1") { throw new RuntimeException("Quarantine marker missing"); } if ((new WP_User($userId))->has_cap("read")) { throw new RuntimeException("Quarantine retained account access"); } $service->restore($userId, 1); if (get_user_meta($userId, "_kiln_cleanup_quarantined", true) !== "") { throw new RuntimeException("Quarantine marker remained after restore"); } if (! (new WP_User($userId))->has_cap("read")) { throw new RuntimeException("Restore did not return subscriber capabilities"); } $events = $wpdb->get_col($wpdb->prepare("SELECT event_type FROM {$wpdb->prefix}kiln_cleanup_audit_events WHERE target_user_id = %d", $userId)); if (! in_array("account_quarantined", $events, true) || ! in_array("account_restored", $events, true)) { throw new RuntimeException("Quarantine audit receipts missing"); }' --allow-root
wp eval 'global $wpdb; $user = get_user_by("login", "quarantine-smoke"); if (! $user instanceof WP_User) { throw new RuntimeException("Smoke user is missing."); } $codec = new \KilnCleanup\Application\ReviewJobSnapshotCodec(); $jobs = new \KilnCleanup\Infrastructure\WpdbReviewJobRepository(); $job = $jobs->create($codec->policySnapshot(new \KilnCleanup\Detection\DetectionPolicy("quarantine-smoke-v1")), $codec->filterSnapshot(new \KilnCleanup\Domain\InventoryFilter()), 1); $wpdb->update($wpdb->prefix . "kiln_cleanup_jobs", ["state" => "completed"], ["id" => $job->id]); (new \KilnCleanup\Infrastructure\WpdbCandidateSnapshotRepository())->insert(new \KilnCleanup\Domain\CandidateSnapshot($job->id, (int) $user->ID, 75, "eligible_for_quarantine", "quarantine-smoke-v1", ["blocked_email_domain"])); $visible = (new \KilnCleanup\Infrastructure\WpdbQuarantineCandidateRepository())->listEligible(50); $matches = array_values(array_filter($visible, static fn (array $candidate): bool => $candidate["user_id"] === (int) $user->ID)); if (count($matches) !== 1 || $matches[0]["email"] !== "quarantine-smoke@example.test") { throw new RuntimeException("Eligible candidates were not deduplicated or did not include the account email."); }' --allow-root
wp eval 'global $wpdb; $candidate = $wpdb->get_row("SELECT job_id, user_id FROM {$wpdb->prefix}kiln_cleanup_candidates ORDER BY id DESC LIMIT 1", ARRAY_A); $before = (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$wpdb->prefix}kiln_cleanup_quarantines WHERE user_id = %d", (int) $candidate["user_id"])); $service = new \KilnCleanup\Application\QuarantineService(new \KilnCleanup\Infrastructure\WpdbQuarantineCandidateRepository(), new \KilnCleanup\Infrastructure\WpdbQuarantineRepository(), new \KilnCleanup\Infrastructure\WordPressUserAccountGateway(), new \KilnCleanup\Infrastructure\QuarantineAuditRecorder()); $service->quarantine((int) $candidate["job_id"], (int) $candidate["user_id"], new \KilnCleanup\Detection\DetectionPolicy("quarantine-smoke-v1"), 1); $service->restore((int) $candidate["user_id"], 1); $after = (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$wpdb->prefix}kiln_cleanup_quarantines WHERE user_id = %d", (int) $candidate["user_id"])); if ($after !== $before + 1) { throw new RuntimeException("Repeated quarantine did not retain separate history"); }' --allow-root
wp eval 'global $wpdb; foreach (["claim_token", "claim_expires_at", "last_error"] as $column) { if ($wpdb->get_var("SHOW COLUMNS FROM {$wpdb->prefix}kiln_cleanup_jobs LIKE \"{$column}\"") !== $column) { throw new RuntimeException("Missing M7 job column: " . $column); }} if (! wp_next_scheduled("kiln_cleanup_run_review_jobs")) { throw new RuntimeException("M7 review worker cron event is not scheduled"); }' --allow-root
wp kiln-cleanup review-jobs run --batches=1 --batch-size=25 --allow-root
wp eval 'do_action("admin_menu");' --allow-root
wp eval 'global $wpdb; $login = "deletion-smoke-" . wp_generate_password(8, false, false); $email = $login . "@example.test"; $userId = wp_create_user($login, "not-a-real-secret", $email); if (is_wp_error($userId)) { throw new RuntimeException("Deletion smoke user could not be created."); } (new WP_User($userId))->set_role("subscriber"); $postId = wp_insert_post(["post_title" => "Deletion smoke", "post_status" => "publish", "post_author" => $userId]); if (! is_int($postId) || $postId < 1) { throw new RuntimeException("Deletion smoke post could not be created."); } $codec = new \KilnCleanup\Application\ReviewJobSnapshotCodec(); $jobs = new \KilnCleanup\Infrastructure\WpdbReviewJobRepository(); $job = $jobs->create($codec->policySnapshot(new \KilnCleanup\Detection\DetectionPolicy("deletion-smoke-v1")), $codec->filterSnapshot(new \KilnCleanup\Domain\InventoryFilter()), 1); $wpdb->update($wpdb->prefix . "kiln_cleanup_jobs", ["state" => "completed"], ["id" => $job->id]); (new \KilnCleanup\Infrastructure\WpdbCandidateSnapshotRepository())->insert(new \KilnCleanup\Domain\CandidateSnapshot($job->id, $userId, 75, "eligible_for_quarantine", "deletion-smoke-v1", ["blocked_email_domain"])); $quarantine = new \KilnCleanup\Application\QuarantineService(new \KilnCleanup\Infrastructure\WpdbQuarantineCandidateRepository(), new \KilnCleanup\Infrastructure\WpdbQuarantineRepository(), new \KilnCleanup\Infrastructure\WordPressUserAccountGateway(), new \KilnCleanup\Infrastructure\QuarantineAuditRecorder()); $quarantine->quarantine($job->id, $userId, new \KilnCleanup\Detection\DetectionPolicy("deletion-smoke-v1"), 1); $wpdb->update($wpdb->prefix . "kiln_cleanup_quarantines", ["quarantined_at" => gmdate("Y-m-d H:i:s", time() - 31 * DAY_IN_SECONDS)], ["user_id" => $userId, "state" => "quarantined"]); $deletion = new \KilnCleanup\Application\PermanentDeletionService(new \KilnCleanup\Infrastructure\WpdbQuarantineRepository(), new \KilnCleanup\Infrastructure\WpdbQuarantineCandidateRepository(), new \KilnCleanup\Infrastructure\WordPressPermanentDeletionGateway(), new \KilnCleanup\Infrastructure\QuarantineAuditRecorder()); $preflight = $deletion->preflight($userId); if (($preflight->contentCounts["post"] ?? 0) < 1) { throw new RuntimeException("Deletion preflight did not summarize authored content."); } $deletion->delete($userId, 1); if (get_userdata($userId) !== false || get_post($postId) !== null) { throw new RuntimeException("Permanent deletion retained account or authored content."); } $event = $wpdb->get_row($wpdb->prepare("SELECT context FROM {$wpdb->prefix}kiln_cleanup_audit_events WHERE event_type = %s AND target_user_id = %d ORDER BY id DESC LIMIT 1", "account_deleted", $userId), ARRAY_A); if (! is_array($event) || str_contains((string) $event["context"], $email)) { throw new RuntimeException("Deletion audit receipt missing or retained email."); }' --allow-root
wp eval 'global $wpdb; $user = get_user_by("login", "quarantine-smoke"); if (! $user instanceof WP_User) { throw new RuntimeException("Prevention smoke user missing."); } update_option("kiln_cleanup_registration_evidence_enabled", "1"); do_action("user_register", $user->ID); $event = $wpdb->get_row($wpdb->prepare("SELECT context FROM {$wpdb->prefix}kiln_cleanup_audit_events WHERE event_type = %s AND target_user_id = %d ORDER BY id DESC LIMIT 1", "registration_observed", $user->ID), ARRAY_A); if (! is_array($event) || str_contains((string) $event["context"], "@")) { throw new RuntimeException("Registration evidence was not redacted."); } add_filter("kiln_cleanup_registration_rate_limited", static fn (): bool => true); $errors = apply_filters("registration_errors", new WP_Error(), "blocked", "blocked@example.test"); if (! $errors->has_errors()) { throw new RuntimeException("Local rate-control integration did not block registration."); }' --allow-root
wp plugin is-active kiln-cleanup --allow-root
echo "Container smoke checks passed."
